import { z } from "zod";

/**
 * Content contract for imported book units (generated by packages/book-importer,
 * consumed by api and web). HTML fields are already sanitized by the importer.
 */

export const Block = z.object({
  id: z.number().int().positive(),
  title: z.string().min(1),
  range: z.object({
    from: z.number().int().positive(),
    to: z.number().int().positive(),
  }),
});
export type Block = z.infer<typeof Block>;

export const TheorySection = z.object({
  letter: z.string().min(1),
  html: z.string(),
});
export type TheorySection = z.infer<typeof TheorySection>;

export const Segment = z.discriminatedUnion("type", [
  z.object({ type: z.literal("text"), text: z.string().min(1) }),
  z.object({ type: z.literal("blank"), id: z.string().min(1), size: z.enum(["short", "long"]) }),
  z.object({ type: z.literal("underline"), text: z.string().min(1) }),
  z.object({ type: z.literal("example"), text: z.string().min(1) }),
]);
export type Segment = z.infer<typeof Segment>;

export const AnswerKind = z.enum(["blanks", "sentence", "ok-or-fix", "open"]);
export type AnswerKind = z.infer<typeof AnswerKind>;

export const ItemAnswer = z.object({
  /** Original answer-key string with HTML stripped (curly apostrophes kept). */
  raw: z.string().min(1),
  /** One entry per blank, in order; each entry lists the accepted alternatives. */
  blanks: z.array(z.array(z.string().min(1)).min(1)),
  kind: AnswerKind,
  /** True when the key cannot be mapped reliably to blanks; the AI check decides. */
  needsAi: z.boolean(),
  aiReason: z.string().optional(),
});
export type ItemAnswer = z.infer<typeof ItemAnswer>;

export const ExerciseItem = z.object({
  num: z.string().min(1),
  /** Worked example: displayed pre-filled, not graded. */
  isExample: z.boolean(),
  lines: z.array(z.array(Segment).min(1)),
  answer: ItemAnswer.optional(),
});
export type ExerciseItem = z.infer<typeof ExerciseItem>;

export const WordBankEntry = z.object({
  text: z.string().min(1),
  used: z.boolean(),
});
export type WordBankEntry = z.infer<typeof WordBankEntry>;

export const Exercise = z.object({
  id: z.string().regex(/^\d+\.\d+$/),
  instruction: z.string(),
  wordBank: z.array(WordBankEntry).optional(),
  passage: z.string().optional(),
  evaluation: z.enum(["auto", "ai"]),
  answerNote: z.string().optional(),
  items: z.array(ExerciseItem).min(1),
});
export type Exercise = z.infer<typeof Exercise>;

export const Unit = z.object({
  number: z.number().int().positive(),
  title: z.string().min(1),
  subtitle: z.string(),
  block: Block,
  theory: z.array(TheorySection),
  exercises: z.array(Exercise),
});
export type Unit = z.infer<typeof Unit>;

export const UnitSummary = z.object({
  number: z.number().int().positive(),
  title: z.string().min(1),
  subtitle: z.string(),
  block: Block,
  file: z.string().min(1),
  exerciseCount: z.number().int().nonnegative(),
  itemCount: z.number().int().nonnegative(),
});
export type UnitSummary = z.infer<typeof UnitSummary>;

export const UnitIndex = z.object({
  units: z.array(UnitSummary),
});
export type UnitIndex = z.infer<typeof UnitIndex>;
